insert into public.site_settings(id,data) values ('main','{"services": [{"title": "Social that connects.", "name": "Social media marketing", "type": "SOCIAL & COMMUNITY", "color": "lavender", "icon": "social", "text": "Make your feed feel like your brand. Content, conversations, and a reason to come back.", "deliverables": ["Social strategy & content calendars", "Bangla & English content", "Community management"], "detail": "We shape a consistent voice and visual direction, plan the content around your audience, and help turn everyday posts into conversations.", "slug": "social-media-marketing", "id": "service-0"}, {"title": "Clicks with a purpose.", "name": "Paid advertising", "type": "PERFORMANCE MARKETING", "color": "blue", "icon": "target", "text": "Get in front of the right people. Put your advertising budget behind a clear plan.", "deliverables": ["Meta & Google campaigns", "Creative testing", "Campaign reporting"], "detail": "We agree campaign goals, shape audiences and creative, and review performance so your next decision has a clear starting point. Advertising spend is separate from service fees.", "slug": "paid-advertising", "id": "service-1"}, {"title": "A brand with a point of view.", "name": "Branding & creative", "type": "IDENTITY & DESIGN", "color": "peach", "icon": "spark", "text": "Look distinctive. Sound like yourself. Give people something to remember.", "deliverables": ["Brand identity & visual direction", "Campaign concepts", "Social & marketing design"], "detail": "We bring your brand personality into a usable visual system, with consistent design and copy across your customer touchpoints.", "slug": "branding-creative", "id": "service-2"}, {"title": "Your best first impression.", "name": "Website design", "type": "WEBSITES & EXPERIENCES", "color": "mint", "icon": "web", "text": "A digital home that looks the part and makes the next step feel easy.", "deliverables": ["Responsive business websites", "Campaign landing pages", "Enquiry-focused user journeys"], "detail": "We design around what visitors need to understand, explore, and do. Your site is built for clear communication across mobile and desktop.", "slug": "website-design", "id": "service-3"}, {"title": "Be found. Stay relevant.", "name": "Search engine optimisation", "type": "SEARCH & DISCOVERY", "color": "ice", "icon": "search", "text": "Show up when your customers are looking. Build a useful, discoverable presence.", "deliverables": ["Local search optimisation", "On-page SEO", "Search-focused content planning"], "detail": "We work on the content and structure that help search engines understand your business, with local discovery in mind. Search results develop over time and vary by competition.", "slug": "search-engine-optimisation", "id": "service-4"}, {"title": "Stories made to move.", "name": "Content & video", "type": "CONTENT PRODUCTION", "color": "pink", "icon": "play", "text": "From a first-frame hook to the final word. Content made for the way people scroll.", "deliverables": ["Short-form video concepts", "Reels & social content", "Campaign copywriting"], "detail": "We match your message to the format, from short video ideas to memorable copy. Every piece starts with your audience and the action you want them to take.", "slug": "content-video", "id": "service-5"}], "steps": [{"name": "Discover", "title": "First, we listen.", "text": "Your business, your audience, your ambitions. We ask the questions that help us understand what progress should look like."}, {"name": "Shape", "title": "Find the right direction.", "text": "We build a practical roadmap with clear channels, creative priorities, deliverables, and a timeline that fits your business."}, {"name": "Create", "title": "Make the idea real.", "text": "Design, content, and campaigns come together. We agree the details with you and bring the work to life."}, {"name": "Refine", "title": "Learn. Adjust. Go again.", "text": "We review results, share what we learn, and use those insights to make the next round of work more focused."}], "faqs": [["Can we start small?", "Absolutely. Begin with one service or one project. We can shape the scope around your immediate priorities and available budget."], ["Do you work in Bangla and English?", "Yes. The language and tone are chosen around your audience. Some brands need Bangla, some need English, and many need both."], ["How much does a project cost?", "Pricing depends on the agreed scope, channels, deliverables, and timeline. Advertising spend is agreed separately from agency fees."], ["Are the creative lab projects real client work?", "The creative lab shows illustrative concepts, not commissioned client work or claimed results. It demonstrates possible creative directions."]], "portfolio": [{"name": "A fresh kind of everyday.", "category": "Branding", "type": "Brand direction", "className": "brand-concept", "desc": "An illustrative identity exploration for a fictional lifestyle brand. Warm packaging, oversized type, and a simple visual language.", "tags": ["Identity", "Packaging", "Art direction"]}, {"name": "Made to stop the scroll.", "category": "Social", "type": "Social campaign", "className": "social-concept", "desc": "An illustrative launch campaign showing how bold art direction, short copy, and a consistent social system can work together.", "tags": ["Social design", "Content", "Campaign"]}, {"name": "Less friction. More discovery.", "category": "Web", "type": "Digital experience", "className": "web-concept", "desc": "An illustrative ecommerce landing page exploring clear product discovery, a strong first impression, and a focused mobile experience.", "tags": ["Web design", "UX", "Mobile"]}], "copy": {"EVERYDAY, REIMAGINED.": "EVERYDAY, REIMAGINED.", "little": "little", "joy.": "joy.", "GOOD THINGS. SIMPLY.": "GOOD THINGS. SIMPLY.", "A MOMENT FOR YOU.": "A MOMENT FOR YOU.", "YOUR NEXT CHAPTER": "YOUR NEXT CHAPTER", "MAKE": "MAKE", "SOME": "SOME", "NOISE.": "NOISE.", "GOOD IDEAS DON''T WHISPER. ↗": "GOOD IDEAS DON''T WHISPER. ↗", "HELLO,": "HELLO,", "POSSIBILITY.": "POSSIBILITY.", "form & everyday": "form & everyday", "OBJECTS WITH INTENTION": "OBJECTS WITH INTENTION", "Less, but": "Less, but", "better.": "better.", "Explore the collection ↗": "Explore the collection ↗", "form.": "form.", "Good design.": "Good design.", "Every day.": "Every day.", "Skip to content": "Skip to content", "Fresh thinking. Local insight. Global possibilities.": "Fresh thinking. Local insight. Global possibilities.", "Let''s make your next move ": "Let''s make your next move ", "Start a project ": "Start a project ", " INDEPENDENT DIGITAL THINKING · BANGLADESH": " INDEPENDENT DIGITAL THINKING · BANGLADESH", "Good ideas": "Good ideas", "deserve a": "deserve a", "bigger stage.": "bigger stage.", "We help ambitious brands find their voice, reach their people, and turn the next big idea into their next big move.": "We help ambitious brands find their voice, reach their people, and turn the next big idea into their next big move.", "Let''s make something matter ": "Let''s make something matter ", " Explore the possibilities": " Explore the possibilities", "STRATEGY. CREATIVE. DIGITAL.": "STRATEGY. CREATIVE. DIGITAL.", "বাংলাদেশ থেকে, আরও দূরে।": "বাংলাদেশ থেকে, আরও দূরে।", "GT / CREATIVE THINKING, IN MOTION": "GT / CREATIVE THINKING, IN MOTION", "THINK": "THINK", "OUTSIDE": "OUTSIDE", "the ordinary.": "the ordinary.", " Your next chapter starts here.": " Your next chapter starts here.", "A LITTLE CURIOUS. A LOT OF POSSIBLE.": "A LITTLE CURIOUS. A LOT OF POSSIBLE.", "Strategy with direction": "Strategy with direction", "Creative with character": "Creative with character", "Digital with purpose": "Digital with purpose", "A little different": "A little different", "01 / WHAT WE BRING TO THE TABLE": "01 / WHAT WE BRING TO THE TABLE", "A fresh perspective.": "A fresh perspective.", "A connected approach.": "A connected approach.", "One brand. Many ways to connect.": "One brand. Many ways to connect.", "We bring the right skills together around what your business needs next.": "We bring the right skills together around what your business needs next.", "02 / THE CREATIVE LAB": "02 / THE CREATIVE LAB", "Less ordinary.": "Less ordinary.", "More possibility.": "More possibility.", "A glimpse of where an idea can go.": "A glimpse of where an idea can go.", "Illustrative concepts. Fresh creative directions.": "Illustrative concepts. Fresh creative directions.", "· CONCEPT": "· CONCEPT", " These are creative explorations, not commissioned client projects.": " These are creative explorations, not commissioned client projects.", "ROOTED HERE. OPEN TO EVERYWHERE.": "ROOTED HERE. OPEN TO EVERYWHERE.", "Thin": "Thin", "Q": "Q", "আপনার ভাবনা,": "আপনার ভাবনা,", "বাড়ুক সম্ভাবনা।": "বাড়ুক সম্ভাবনা।", "BANGLADESH ↗ BEYOND": "BANGLADESH ↗ BEYOND", "IDEAS INTO GROWTH.": "IDEAS INTO GROWTH.", "03 / HELLO, WE''RE GLOBAL THINQ": "03 / HELLO, WE''RE GLOBAL THINQ", "Local understanding.": "Local understanding.", "Unboxed thinking.": "Unboxed thinking.", "A small business finding its feet. A brand ready for its next chapter. Your story deserves a digital presence that feels like you.": "A small business finding its feet. A brand ready for its next chapter. Your story deserves a digital presence that feels like you.", "We bring an understanding of Bangladesh''s audiences together with an open, curious approach to creative work. Every plan starts with your business, not a template.": "We bring an understanding of Bangladesh''s audiences together with an open, curious approach to creative work. Every plan starts with your business, not a template.", "People before platforms.": "People before platforms.", "Start with your audience. Choose the channels that make sense.": "Start with your audience. Choose the channels that make sense.", "Ideas with intention.": "Ideas with intention.", "Creative choices that support a clear business goal.": "Creative choices that support a clear business goal.", "Clear, from the start.": "Clear, from the start.", "Agreed scope, honest conversations, and a shared direction.": "Agreed scope, honest conversations, and a shared direction.", "Meet your next creative direction ": "Meet your next creative direction ", "04 / FROM A WHAT-IF TO WHAT''S NEXT": "04 / FROM A WHAT-IF TO WHAT''S NEXT", "A little structure.": "A little structure.", "A lot of room to think.": "A lot of room to think.", "Good collaboration needs a clear path.": "Good collaboration needs a clear path.", "Here''s ours.": "Here''s ours.", "05 / YOUR NEXT CHAPTER": "05 / YOUR NEXT CHAPTER", "Have a": "Have a", "what if?": "what if?", "Let''s make": "Let''s make", "it happen": "it happen", "Bring us the big idea, the small question, or the challenge you haven''t quite figured out yet.": "Bring us the big idea, the small question, or the challenge you haven''t quite figured out yet.", " Based in Bangladesh. Thinking beyond.": " Based in Bangladesh. Thinking beyond.", "Tell us a little about your project.": "Tell us a little about your project.", "Your name": "Your name", "Business name": "Business name", "Email address": "Email address", "What can we help with?": "What can we help with?", "What do you have in mind?": "What do you have in mind?", "Create my project brief ": "Create my project brief ", "Create and download a brief to share with Global ThinQ. This form doesn''t send an enquiry. Your details stay in your browser.": "Create and download a brief to share with Global ThinQ. This form doesn''t send an enquiry. Your details stay in your browser.", "A FEW THINGS, CLEARED UP": "A FEW THINGS, CLEARED UP", "Good questions.": "Good questions.", "Straight answers.": "Straight answers.", "Independent thinking.": "Independent thinking.", "Connected digital experiences.": "Connected digital experiences.", "TAKE A LOOK": "TAKE A LOOK", "Our services": "Our services", "Creative lab": "Creative lab", "The studio": "The studio", "MAKE A MOVE": "MAKE A MOVE", "How we work": "How we work", "Bangladesh ↗ Beyond": "Bangladesh ↗ Beyond", "Think beyond": "Think beyond", "ordinary.": "ordinary.", "Ideas into growth.": "Ideas into growth.", "Back to top ↑": "Back to top ↑", "Build a brief for this service ": "Build a brief for this service ", "ILLUSTRATIVE CREATIVE EXPLORATION": "ILLUSTRATIVE CREATIVE EXPLORATION", "Let''s explore your direction ": "Let''s explore your direction ", "READY FOR THE NEXT STEP": "READY FOR THE NEXT STEP", "Your brief, ready to go.": "Your brief, ready to go.", "Download brief ↓": "Download brief ↓", "Keep editing": "Keep editing"}, "contact": {"address": "Dhaka, Bangladesh", "email": "", "phone": "", "facebook": "", "instagram": "", "linkedin": ""}, "seo": {"seo_title": "Global ThinQ | Digital Marketing & IT Services in Dhaka", "meta_description": "Social media marketing, creative campaigns, websites and IT services from Global ThinQ in Dhaka, Bangladesh."}, "hero_image": "/assets/creative-sculpture.png", "logo": "/assets/global-thinq-logo.svg", "hero_alt": "Iridescent chrome sculpture with blue and violet reflections"}'::jsonb);
